import{_ as d,o as a,c as e,a6 as r}from"./chunks/framework.Bd7kzaCy.js";const b=JSON.parse('{"title":"第九部分　行动者状态与人格假设","description":"","frontmatter":{"title":"第九部分　行动者状态与人格假设"},"headers":[],"relativePath":"theory/part-09.md","filePath":"theory/part-09.md"}'),h={name:"theory/part-09.md"};function o(i,t,n,p,s,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<div class="theory-source"><p><a id="part_9"></a></p><h1 id="part-title-9" tabindex="-1">第九部分　行动者状态与人格假设 <a class="header-anchor" href="#part-title-9" aria-label="Permalink to &quot;第九部分　行动者状态与人格假设 {#part-title-9}&quot;">​</a></h1><p>本部分把“人”接入多圈层推演，但不把人压缩成一个固定标签。事件中的行动者既携带相对缓慢的长期倾向，也处在阶段性的角色、关系和资源位置中，还会受到即时情绪、身体状态、信息与机会的影响。同一个人在不同圈层里可能呈现不同的行动方式；这些差异不必由虚伪、人格分裂或本质变化解释，也可能来自角色激活、风险结构、可见信息、奖惩、退出能力和受影响位置的改变。</p><h2 id="section-9-1" tabindex="-1">9.1　行动者不是单一变量 <a class="header-anchor" href="#section-9-1" aria-label="Permalink to &quot;9.1　行动者不是单一变量 {#section-9-1}&quot;">​</a></h2><p>行动者记录的最小形式是：</p><p>A* = &lt;行动者 ID，观察窗，圈层成员关系，角色，慢变量，中变量，快变量，物质条件，体验—意义条件，未知项，证据状态，隐私与允许用途&gt;。</p><p>星号表示这仍是一份候选状态描述。行动者的名字、职业、社会身份或一次行为都不能自动填满其状态。任何无法观察、没有来源、当事人拒绝披露或彼此冲突的信息都要保留为不同类型的未知，而不是由模型以“常识”补齐。</p><table tabindex="0"><thead><tr><th>字段</th><th>回答的问题</th><th>最低记录要求</th><th>不能推出</th></tr></thead><tbody><tr><td>行动者 ID</td><td>当前分析指向谁或哪个行动单元</td><td>稳定引用、时间窗、同一性边界</td><td>对其全部生活的代表权</td></tr><tr><td>圈层成员关系</td><td>他此刻处于哪些关系与制度位置</td><td>圈层 ID、进入/退出、成员依据</td><td>对圈层目标的认同</td></tr><tr><td>角色</td><td>他被期待、允许或迫使做什么</td><td>角色来源、权利、责任、冲突</td><td>实际能力与真实意愿</td></tr><tr><td>状态变量</td><td>当前有哪些可观察或候选状态</td><td>时间带、来源、状态、反证</td><td>稳定人格本质</td></tr><tr><td>条件</td><td>什么使某种行为更可行或更危险</td><td>物质与体验—意义分别登记</td><td>单一原因决定行为</td></tr><tr><td>未知项</td><td>哪些关键信息暂时不可用</td><td>缺失类型、影响、获取边界</td><td>可由模型自由插补</td></tr></tbody></table><h2 id="section-9-2" tabindex="-1">9.2　慢变量、中变量与快变量 <a class="header-anchor" href="#section-9-2" aria-label="Permalink to &quot;9.2　慢变量、中变量与快变量 {#section-9-2}&quot;">​</a></h2><p>三个时间带不是三类人格，也不是互不相干的抽屉。它们用于约束更新速度：什么可以在一次事件后改变，什么需要多个回合才能改变，什么只有在更长时间、跨情境证据或重大生活重构后才应更新。</p><h3 id="section-9-2-1" tabindex="-1">9.2.1　慢变量 <a class="header-anchor" href="#section-9-2-1" aria-label="Permalink to &quot;9.2.1　慢变量 {#section-9-2-1}&quot;">​</a></h3><p>慢变量包括长期价值排序、习惯化解释方式、长期能力与资源位置、身份承诺、信任与依恋倾向等候选状态。称其为“慢”，只表示在当前研究窗口内变化相对缓慢，不表示天生、不变、真实自我或跨所有情境普遍成立。</p><p>慢变量须有足以支持所称持续性的跨时间证据；若进一步声称跨情境稳定，还需覆盖不同情境的材料。一次测量所引用的量表效度不等于该人在所有场景中均已被观察。若某一倾向只在一个高压圈层出现，而在其他圈层没有出现，就必须保留“由该圈层激活”的竞争解释。若资源位置、创伤、重大关系变化、长期学习或制度迁移改变了行动模式，慢变量也应被更新、分裂为条件性变量或退役。</p><p>习得倾向可以通过反复的家庭、学校、工作与同伴实践形成：谁有时间练习，谁得到纠正或鼓励，何种说话、姿态、资格和判断被奖赏，会影响后来觉得自然、可能或值得尝试的行动。这样的历史形成过程不同于一次策略选择，也不同于人格本质。需要把训练机会、反复实践、机构回应和跨情境差异连接起来，不能从一个动作反推家庭出身或完整生活史。</p><p>同一行动者可能携带来自多种社会化经历的不同倾向。旧倾向进入新环境可能失配，某种资源在一个领域被承认、在另一个领域没有回报，反复的新实践又可能改变原有倾向。慢变量应允许按情境拆分、修订或退役；群体平均关联不填满个人状态，偏离群体常态也不自动成为异常。</p><h3 id="section-9-2-2" tabindex="-1">9.2.2　中变量 <a class="header-anchor" href="#section-9-2-2" aria-label="Permalink to &quot;9.2.2　中变量 {#section-9-2-2}&quot;">​</a></h3><p>中变量包括角色认同、阶段性目标、关系预期、联盟位置、疲劳积累、近期声誉和阶段性信任。它们通常跨越多个互动回合，但可能随项目结束、组织重组、关系修复、公开事件或资源变化而改变。</p><p>中变量是个人与圈层互构的主要接口。圈层通过角色、指标、声誉、奖惩和归属感塑造中变量；行动者又通过履责、抵抗、退出、结盟、解释和制度写回改变圈层。只观察其中一侧，会把结构压力误写成人格缺陷，或把个人选择完全消解为环境决定。</p><h3 id="section-9-2-3" tabindex="-1">9.2.3　快变量 <a class="header-anchor" href="#section-9-2-3" aria-label="Permalink to &quot;9.2.3　快变量 {#section-9-2-3}&quot;">​</a></h3><p>快变量包括即时情绪、唤醒、注意、恐惧、冲动、当前信念、短时身体状态、机会感知和当前策略。快变量必须绑定具体时点和事件，不能用一次快变量状态推断长期人格。</p><p>快变量虽然短暂，却可能通过阈值、公开留痕、不可逆行动或他人反馈进入中变量和慢变量。例如，一次短时恐惧本身不等于长期不信任；但若恐惧导致公开退缩、组织惩罚、关系破裂和反复回避，它可能经多圈层反馈形成更持久的路径。推演必须写出这条通道，不能把结果倒推为“他本来就不信任”。</p><table tabindex="0"><thead><tr><th>时间带</th><th>典型变化速度</th><th>证据要求</th><th>允许的事件后更新</th><th>常见误用</th></tr></thead><tbody><tr><td>慢变量</td><td>相对于当前窗口变化较慢；可能跨月、跨年或跨重大阶段</td><td>持续性看跨时间材料；跨情境主张另需相应覆盖，来源相依与反例分别记录</td><td>新证据可调整支持度或取值，改变是否持久另行核验</td><td>把标签写成天性或规定所有人相同更新速度</td></tr><tr><td>中变量</td><td>多个互动回合至一个阶段</td><td>同阶段重复观察、角色与圈层条件</td><td>可随关系、项目、组织与资源变化更新</td><td>把角色反应写成人格</td></tr><tr><td>快变量</td><td>分钟、小时、数日</td><td>绑定时点、事件、身体与信息状态</td><td>可在每个事件后更新</td><td>用一次情绪预测全部未来</td></tr></tbody></table><h2 id="section-9-3" tabindex="-1">9.3　人格只能作为有条件的慢变量假设 <a class="header-anchor" href="#section-9-3" aria-label="Permalink to &quot;9.3　人格只能作为有条件的慢变量假设 {#section-9-3}&quot;">​</a></h2><p>人格在本框架中不是禁词，但必须降到合适的位置：它是一组试图压缩跨时间、跨情境行为差异的慢变量假设。一个人格假设至少要说明观察到什么行为、在哪些情境观察到、在哪些情境没有观察到、持续多久、有哪些来源、有哪些反例、还有哪些更简单解释，以及该假设允许被用来做什么。</p><p>人格假设的状态只能是观察记录、得到支持的假设、候选、争议、未知或退役。观察记录指具体可核查行为，不是人格结论；得到支持的假设仍然带时间窗、情境和误差；候选只是需要检验；争议表示证据或解释冲突；未知表示当前不能判断；退役表示它不再提供增益或产生不可接受误导。</p><table tabindex="0"><thead><tr><th>人格假设卡</th><th>必须填写的内容</th></tr></thead><tbody><tr><td>假设描述</td><td>用可区分、可反驳的语言描述倾向，不使用侮辱性或病理化标签</td></tr><tr><td>行为指标</td><td>具体行为、选择或表达，不以分析者感受代替</td></tr><tr><td>已观察情境</td><td>圈层、角色、压力、资源、信息和时间窗</td></tr><tr><td>未观察情境</td><td>尚未覆盖或出现相反行为的场景</td></tr><tr><td>竞争解释</td><td>角色要求、短时情绪、物质约束、策略、文化规范、测量偏差等</td></tr><tr><td>反证</td><td>与假设不一致的事实、证词和结果</td></tr><tr><td>当前状态</td><td>候选、支持、争议、未知或退役</td></tr><tr><td>允许用途</td><td>研究、沟通、情景推演或其他受限用途</td></tr><tr><td>禁止用途</td><td>临床诊断、人格本质裁决、歧视性筛选、自动授权或处罚</td></tr></tbody></table><p>本框架不进行临床诊断、精神医学诊断或未经授权的心理测评。即使外部专业诊断存在，也只能以有来源、有权限、有适用边界的材料进入，不能由框架自行生成、扩大或用于与原目的不相容的处置。</p><h2 id="section-9-4" tabindex="-1">9.4　角色激活与圈层条件 <a class="header-anchor" href="#section-9-4" aria-label="Permalink to &quot;9.4　角色激活与圈层条件 {#section-9-4}&quot;">​</a></h2><p>一个行动者进入不同圈层时，至少有六项条件可能变化：可见信息、可用资源、奖惩、责任、身份激活和退出能力。行为差异应把这些条件、独立测量的个人差异与二者交互作为可竞争的解释；调查时先查容易改变的情境，不意味着在模型中将共享解释量预先全部分给情境。</p><p>例如，一个人在家庭圈层中沉默、在工作圈层中强势、在朋友圈层中开放。至少存在以下竞争解释：家庭中的历史冲突提高表达成本；工作角色给予正式权限；朋友关系提供较低惩罚和更高信任；三个场景激活了不同身份；观察者在不同圈层掌握的信息不同；行为样本的时间窗不一致。比较时应固定相同目标、资料划分、可用信息、复杂度与测量预算，分别检验个人差异模型、情境模型及交互模型。人格指标对新窗口行为有增益，可以支持限定预测；这仍不证明它是主要因果机制、天生本质或干预优先项。若人物总与单一情境成对出现，重复观察也不能自行拆开两者贡献。</p><p>角色激活记录应回答：哪个事件激活了哪个角色；角色来自正式规则、非正式期待、自我承诺还是威胁；行动者是否认同；角色与其他角色是否冲突；角色允许什么、禁止什么、要求承担什么成本；退出角色需要什么条件。</p><p>跨情境稳定性还须明确所问的是排序、平均水平、状态波动分布，还是“在特定条件下怎样反应”的轮廓。一个人接触各类情境的比例改变，可以使总体行为均值变化而条件反应未变。长期资源与能力也是慢变量；统计模型中的个人随机截距只表示尚未分解的个体差异，不能直接命名为人格。</p><h2 id="section-9-5" tabindex="-1">9.5　个人影响圈层与圈层影响个人 <a class="header-anchor" href="#section-9-5" aria-label="Permalink to &quot;9.5　个人影响圈层与圈层影响个人 {#section-9-5}&quot;">​</a></h2><p>双向影响必须拆成两条可检验链。</p><p>圈层影响个人的链条可以写为：圈层规则或事件改变信息、资源、风险、角色或意义条件，经行动者的感知与能力形成快变量变化，再通过重复反馈、公开留痕或关系重构进入中变量或慢变量。</p><p>个人影响圈层的链条可以写为：行动者的表达、劳动、拒绝、退出、桥接、结盟或创新改变圈层的资源流、角色分配、共同解释、成员边界、制度记录或外部接口，继而改变其他成员和圈层的状态。</p><table tabindex="0"><thead><tr><th>方向</th><th>起点</th><th>必须找到的通道</th><th>可观察结果</th><th>主要反例</th></tr></thead><tbody><tr><td>圈层→个人</td><td>规则、事件、资源或意义变化</td><td>信息、奖惩、身体负荷、角色、声誉、归属</td><td>状态、行为或选择概率变化</td><td>同样暴露下没有变化，或变化由外部事件解释</td></tr><tr><td>个人→圈层</td><td>表达、行动、拒绝、退出或桥接</td><td>资源流、成员模仿、制度写回、网络传播、代表机制</td><td>规则、边界、分配、关系或集体状态变化</td><td>行动未被接收，或圈层变化先于个人行动</td></tr><tr><td>圈层↔个人反馈</td><td>上述两条链连续闭合</td><td>返回通道、时延、阈值与留痕</td><td>后续回合的转移概率改变</td><td>只有信号到达，没有改变后续状态</td></tr></tbody></table><p>“互相影响”不是解释完成，而是要求分析者继续寻找方向、通道、时延、阈值、损耗和反事实。</p><h2 id="section-9-6" tabindex="-1">9.6　证据等级与状态升级 <a class="header-anchor" href="#section-9-6" aria-label="Permalink to &quot;9.6　证据等级与状态升级 {#section-9-6}&quot;">​</a></h2><p>行动者变量的升级遵循保守次序。模型可以从残差中提出候选，但候选不能直接升级为事实。一次自述、一次他述、一次行为观察和一次量表结果分别带有不同偏差；多来源一致也不自动排除共同环境、共同叙事或同一测量偏差。</p><table tabindex="0"><thead><tr><th>当前状态</th><th>可以做什么</th><th>升级所需</th><th>必须保留</th></tr></thead><tbody><tr><td>未知</td><td>提出问题、标记影响</td><td>合法且合适的新观察</td><td>未知类型和不获取的理由</td></tr><tr><td>候选</td><td>进入情景推演，设计最小检验</td><td>预先声明的指标、时间窗与反例门</td><td>竞争候选、隐私和风险</td></tr><tr><td>得到支持的假设</td><td>在限定情境中用于解释或前瞻</td><td>样本外复核、跨情境检验或独立来源</td><td>适用边界、反证和误差</td></tr><tr><td>观察记录</td><td>描述具体时点发生的行为或状态</td><td>来源完整性与观察合同</td><td>不把行为升级为人格</td></tr><tr><td>争议</td><td>并列冲突材料，降低输出强度</td><td>独立复核或新的区分性证据</td><td>各方位置与利益</td></tr><tr><td>退役</td><td>保留历史，不再参与当前推演</td><td>新版本只能追加退役理由</td><td>旧判断造成的影响和补救</td></tr></tbody></table><p>若一个变量只有在看到结果后才被提出，它可以帮助解释和生成下一轮检验，但不能回头支撑原预测。若同一变量的定义、时间带或指标被更改，应生成新版本，不能覆盖旧失败。</p><h2 id="section-9-7" tabindex="-1">9.7　物质条件与体验—意义条件进入行动者状态 <a class="header-anchor" href="#section-9-7" aria-label="Permalink to &quot;9.7　物质条件与体验—意义条件进入行动者状态 {#section-9-7}&quot;">​</a></h2><p>行动者的物质条件包括身体负荷、健康与睡眠的可观察部分、时间、空间、资金、工具、交通、照护责任、法律地位和实际退出能力。体验—意义条件包括感受、期待、记忆、身份、信任、羞耻、希望、恐惧、承诺、合法性感知和价值冲突。</p><p>两组条件按当前问题的相关性分别记录。若任务只需一个充分的技术或数量指标，不强迫收集无关私人体验；若结论涉及生活机会、意义或自主，则不能用物质总量替代相应经验。物质匮乏可能提高压力，却不自动决定行动者的意义解释；积极信念可能提高坚持，却不能消除资源、身体或制度约束。跨通道推论必须指出：何种物质变化通过何种体验机制改变行为，或何种意义变化通过何种行动改变物质条件。</p><p>身份还具有不能归入个人体验的制度面向。自我认同、他人归类、行政登记、法定资格和实际待遇须分别记录；一个称谓可以改变招聘、服务、举证或申诉入口，即使本人并不接受该称谓。制度性地位与尊严体验可以相互作用，却不互相证明。研究者使用的类别及比较组也须接受当事人异议和版本审查。</p><p>受约束不等于没有行动。可信威胁下由本人签字，与身体被装置推动留下相同字迹，具有不同过程；前者可以仍有本人行动，而安全拒绝和有效同意并未成立。行为归属、知情、控制、可行替代、责难与补救各需依据，因果说明既不自动免责，也不自动证明应受责难。</p><h2 id="section-9-8" tabindex="-1">9.8　隐私、缺席与拒绝披露 <a class="header-anchor" href="#section-9-8" aria-label="Permalink to &quot;9.8　隐私、缺席与拒绝披露 {#section-9-8}&quot;">​</a></h2><p>越接近个体，误用成本越高。行动者记录要区分公开、情境限定、敏感、高度敏感和拒绝披露。允许用途必须与收集目的、授权和受影响者保护一致；用于沟通的材料不自动适用于招聘、保险、执法、医疗、惩罚或公开评价。</p><p>拒绝披露不是敌意、欺骗、无知或风险的证据。沉默可能来自安全、创伤、隐私、语言、信任、权力差异或合理的不合作。分析者只能登记“没有可用信息”以及这对推演造成的限制，不能用人格推断填补。</p><h2 id="section-9-9" tabindex="-1">9.9　行动者状态快照 <a class="header-anchor" href="#section-9-9" aria-label="Permalink to &quot;9.9　行动者状态快照 {#section-9-9}&quot;">​</a></h2><p>一次可审计快照至少包含以下内容：</p><table tabindex="0"><thead><tr><th>区段</th><th>记录内容</th><th>输出上限</th></tr></thead><tbody><tr><td>观察边界</td><td>行动者、时间窗、观察位置、资料截止</td><td>限定当前样本</td></tr><tr><td>圈层与角色</td><td>成员关系、角色、冲突、进入退出能力</td><td>不推定认同与共同目标</td></tr><tr><td>慢/中/快变量</td><td>每项的状态、来源、时点、反证</td><td>不作人格本质判断</td></tr><tr><td>双通道条件</td><td>物质条件与体验—意义条件</td><td>不相互替代</td></tr><tr><td>竞争解释</td><td>结构、角色、策略、测量与偶然因素</td><td>保留不可区分项</td></tr><tr><td>隐私与用途</td><td>等级、授权、禁止用途</td><td>不越过用途边界</td></tr><tr><td>更新条件</td><td>新事件触达哪些变量、何时复核</td><td>不同步刷新全部状态</td></tr></tbody></table><p>快照保留其观察截止与信息取得时点。新事件到来时，先判断它触达哪些通道和时间带，再更新相应变量；时间推进本身触发的自主变化，按已经登记的动力规则另行计算。没有新观测或可靠推进规则时，可以保留最后观测值及其时点，或转为未知，但不得把旧观测值当作当前真实状态。模型重新运行也不构成所有变量同时改变的证据。</p><h2 id="section-9-10" tabindex="-1">9.10　一个事件中的行动者分析示例 <a class="header-anchor" href="#section-9-10" aria-label="Permalink to &quot;9.10　一个事件中的行动者分析示例 {#section-9-10}&quot;">​</a></h2><p>设某项目负责人在公开会议中突然否决团队方案。观察记录只能确认否决行为、会议语境、表达内容和可见后果。快变量候选可能包括时间压力、身体疲劳、威胁感知和即时愤怒；中变量候选可能包括项目目标、角色责任、近期信任下降和声誉风险；慢变量候选可能包括对不确定性的长期容忍度，但这需要跨情境证据。</p><p>同时要检查圈层：管理层是否刚改变指标，团队是否存在资源短缺，平台舆论是否提高公开失败成本，家庭照护是否压缩时间，组织文化是否奖励强硬决策。个人否决可能改变团队信任和后续表达，团队沉默又可能强化负责人“只有强制才有效”的信念，形成反馈。如果只写“控制型人格”，多条可干预通道就会被遮蔽；如果只写“结构决定”，行动者的选择、责任和桥接能力又会消失。</p><p>合理输出应是分层的：确认的行为事实；得到何种支持的状态假设；圈层条件与双向通道；下一步最有区分力的观察；在证据不足时保持哪些未知。该输出可以进入第十一部分的路径推演，但不能自行产生对当事人的诊断、处罚或强制权限。</p><h2 id="section-9-11" tabindex="-1">9.11　本部分的停止位置 <a class="header-anchor" href="#section-9-11" aria-label="Permalink to &quot;9.11　本部分的停止位置 {#section-9-11}&quot;">​</a></h2><p>行动者状态层可以说明：当前有哪些可观察状态和候选变量；哪些变化可能由角色与圈层激活；个人与圈层通过什么通道互构；新事件可能先触达哪些时间带；哪些信息仍未知或受隐私保护。</p><p>本框架不裁定一个人的本质；任何专业评估也不等于人的本体定义。人格描述的临床意义及适用范围，应由合格专业人员依相应证据、有效授权和当事人参与进行评估，不能由本框架单独给出。未来路径进入条件前瞻，价值和行动进入规范选择及授权层；预测、专业身份和标签均不自动产生处置权。</p></div>',1)])])}const u=d(h,[["render",o]]);export{b as __pageData,u as default};
